from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from pydantic import BaseModel, Field
from travel_tools import create_itinerary, replan_trip, find_places, list_destinations

app = FastAPI(title="Wayvora AI", description="A thoughtful travel-planning studio")

class TripRequest(BaseModel):
    destination: str = "Jaipur"
    days: int = Field(default=3, ge=1, le=7)
    travelers: int = Field(default=2, ge=1, le=12)
    budget_inr: int = Field(default=12000, ge=0, le=10000000)
    interests: list[str] = ["history", "food", "culture"]
    travel_style: str = "balanced"

@app.get("/", response_class=HTMLResponse)
def home():
    return HTML

@app.get("/api/health")
def health():
    return {"status": "ok", "project": "Wayvora AI"}

@app.get("/api/destinations")
def destinations():
    return {"destinations": list_destinations()}

@app.get("/api/places")
def places(destination: str = "Jaipur"):
    return find_places(destination)

@app.post("/api/plan")
def plan(req: TripRequest):
    return create_itinerary(req.destination, req.days, req.travelers, req.budget_inr, req.interests, req.travel_style)

@app.post("/api/replan")
def replan(req: TripRequest):
    return replan_trip(req.destination, req.days, req.travelers, req.budget_inr, req.interests, req.travel_style)

